CREATE TABLE public.staff_fee_limits (user_id uuid PRIMARY KEY, min_transaction_percentage numeric NOT NULL DEFAULT 2 CHECK (min_transaction_percentage BETWEEN 0 AND 100), min_transaction_fixed numeric NOT NULL DEFAULT 1 CHECK (min_transaction_fixed BETWEEN 0 AND 1000000), min_withdrawal_fee numeric NOT NULL DEFAULT 3 CHECK (min_withdrawal_fee BETWEEN 0 AND 1000000), updated_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_fee_limits TO authenticated; GRANT ALL ON public.staff_fee_limits TO service_role;
ALTER TABLE public.staff_fee_limits ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_fee_limits_read ON public.staff_fee_limits FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.seller_withdrawal_blocks (seller_user_id uuid PRIMARY KEY, blocked_by uuid NOT NULL, reason text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seller_withdrawal_blocks TO authenticated; GRANT ALL ON public.seller_withdrawal_blocks TO service_role;
ALTER TABLE public.seller_withdrawal_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY withdrawal_blocks_read ON public.seller_withdrawal_blocks FOR SELECT TO authenticated USING (seller_user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (blocked_by=auth.uid() AND public.has_role(auth.uid(),'employee')));
CREATE OR REPLACE FUNCTION app_private.staff_permission_allowed(_key text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT _key=ANY(ARRAY['view_sellers','view_transactions','view_financial','view_disputes','view_withdrawals','approve_kyc','reject_kyc','approve_product','review_products','suspend_products','edit_fees','edit_seller_notes','request_refund','manage_med','freeze_seller_withdrawals','view_support','respond_support','view_analytics','view_rewards','ship_rewards']) $$;
CREATE OR REPLACE FUNCTION app_private.has_staff_permission(_user_id uuid,_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('employee','manager')) AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user_id AND frozen=true) AND EXISTS(SELECT 1 FROM public.staff_permissions WHERE user_id=_user_id AND permission_key=ANY(ARRAY[_key,CASE _key WHEN 'sellers.view' THEN 'view_sellers' WHEN 'sellers.edit' THEN 'edit_seller_notes' WHEN 'fees.edit' THEN 'edit_fees' WHEN 'kyc.approve' THEN 'approve_kyc' WHEN 'kyc.reject' THEN 'reject_kyc' WHEN 'products.view' THEN 'review_products' WHEN 'products.review' THEN 'approve_product' WHEN 'products.suspend' THEN 'suspend_products' WHEN 'transactions.view' THEN 'view_transactions' WHEN 'transactions.refund' THEN 'request_refund' WHEN 'withdrawals.view' THEN 'view_withdrawals' WHEN 'support.view' THEN 'view_support' WHEN 'support.reply' THEN 'respond_support' WHEN 'disputes.view' THEN 'view_disputes' WHEN 'disputes.manage' THEN 'manage_med' WHEN 'analytics.view' THEN 'view_analytics' ELSE _key END])) AND _key NOT IN ('sellers.ban','sellers.delete_account','sellers.block','login_as_user','freeze_seller_balance','withdrawals.approve','withdrawals.reject')) $$;
CREATE OR REPLACE FUNCTION app_private.configure_staff(_actor uuid,_user_id uuid,_permissions text[],_percentage numeric,_fixed numeric,_withdrawal numeric,_commission numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _before jsonb; BEGIN
IF NOT public.has_role(_actor,'admin') THEN RAISE EXCEPTION 'admin only'; END IF;
IF NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_user_id AND role IN ('employee','manager')) OR public.has_role(_user_id,'admin') THEN RAISE EXCEPTION 'Invalid staff target'; END IF;
IF _permissions IS NULL OR cardinality(_permissions)>50 OR EXISTS(SELECT 1 FROM unnest(_permissions) p WHERE NOT app_private.staff_permission_allowed(p) OR p IS NULL) THEN RAISE EXCEPTION 'Invalid permissions'; END IF;
IF _percentage IS NULL OR _fixed IS NULL OR _withdrawal IS NULL OR _commission IS NULL OR _percentage NOT BETWEEN 0 AND 100 OR _fixed NOT BETWEEN 0 AND 1000000 OR _withdrawal NOT BETWEEN 0 AND 1000000 OR _commission NOT BETWEEN 0 AND 50 THEN RAISE EXCEPTION 'Invalid limits'; END IF;
PERFORM 1 FROM profiles WHERE user_id=_user_id FOR UPDATE;
SELECT jsonb_build_object('permissions',(SELECT jsonb_agg(permission_key) FROM staff_permissions WHERE user_id=_user_id),'limits',(SELECT to_jsonb(l) FROM staff_fee_limits l WHERE user_id=_user_id)) INTO _before;
DELETE FROM staff_permissions WHERE user_id=_user_id;
INSERT INTO staff_permissions(user_id,permission_key,granted_by) SELECT _user_id,p,_actor FROM (SELECT DISTINCT unnest(_permissions) p) k;
INSERT INTO staff_fee_limits(user_id,min_transaction_percentage,min_transaction_fixed,min_withdrawal_fee,updated_by) VALUES(_user_id,_percentage,_fixed,_withdrawal,_actor) ON CONFLICT(user_id) DO UPDATE SET min_transaction_percentage=EXCLUDED.min_transaction_percentage,min_transaction_fixed=EXCLUDED.min_transaction_fixed,min_withdrawal_fee=EXCLUDED.min_withdrawal_fee,updated_by=_actor,updated_at=now();
INSERT INTO staff_commission_config(user_id,base_pct,base,is_active) VALUES(_user_id,_commission,'net_amount',true) ON CONFLICT(user_id) DO UPDATE SET base_pct=_commission;
INSERT INTO staff_audit_log(staff_user_id,action,entity_type,entity_id,before,after) VALUES(_actor,'configure_staff','staff',_user_id::text,_before,jsonb_build_object('permissions',_permissions,'percentage',_percentage,'fixed',_fixed,'withdrawal',_withdrawal,'commission',_commission));
END $$;
REVOKE ALL ON FUNCTION app_private.configure_staff(uuid,uuid,text[],numeric,numeric,numeric,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION app_private.configure_staff(uuid,uuid,text[],numeric,numeric,numeric,numeric) TO service_role;
CREATE OR REPLACE FUNCTION public.configure_staff_service(_actor uuid,_user_id uuid,_permissions text[],_percentage numeric,_fixed numeric,_withdrawal numeric,_commission numeric) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT app_private.configure_staff($1,$2,$3,$4,$5,$6,$7) $$;
REVOKE ALL ON FUNCTION public.configure_staff_service(uuid,uuid,text[],numeric,numeric,numeric,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.configure_staff_service(uuid,uuid,text[],numeric,numeric,numeric,numeric) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_configure_staff(_user_id uuid,_permissions text[],_percentage numeric,_fixed numeric,_withdrawal numeric,_commission numeric) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,app_private AS $$ BEGIN PERFORM app_private.configure_staff_authenticated(_user_id,_permissions,_percentage,_fixed,_withdrawal,_commission); END $$;
CREATE OR REPLACE FUNCTION app_private.configure_staff_authenticated(_user_id uuid,_permissions text[],_percentage numeric,_fixed numeric,_withdrawal numeric,_commission numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,app_private AS $$ BEGIN PERFORM app_private.configure_staff(auth.uid(),_user_id,_permissions,_percentage,_fixed,_withdrawal,_commission); END $$;
REVOKE ALL ON FUNCTION app_private.configure_staff_authenticated(uuid,text[],numeric,numeric,numeric,numeric),public.admin_configure_staff(uuid,text[],numeric,numeric,numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION app_private.configure_staff_authenticated(uuid,text[],numeric,numeric,numeric,numeric),public.admin_configure_staff(uuid,text[],numeric,numeric,numeric,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_manager_fee_limits() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _limits public.staff_fee_limits; _uid uuid:=auth.uid(); BEGIN
IF _uid IS NULL OR public.has_role(_uid,'admin') THEN RETURN NEW; END IF;
IF NOT public.has_staff_permission(_uid,'fees.edit') OR public.has_role(_uid,'partner') THEN RAISE EXCEPTION 'Fee permission required'; END IF;
IF NOT EXISTS(SELECT 1 FROM manager_seller_assignments WHERE manager_user_id=_uid AND seller_user_id=NEW.user_id) THEN RAISE EXCEPTION 'Seller not assigned'; END IF;
SELECT * INTO _limits FROM staff_fee_limits WHERE user_id=_uid; IF NOT FOUND THEN RAISE EXCEPTION 'Owner must configure fee limits'; END IF;
IF NEW.transaction_percentage IS NULL OR NEW.transaction_fixed IS NULL OR NEW.withdrawal_fee IS NULL OR NEW.transaction_percentage < _limits.min_transaction_percentage OR NEW.transaction_fixed < _limits.min_transaction_fixed OR NEW.withdrawal_fee < _limits.min_withdrawal_fee THEN RAISE EXCEPTION 'Fee below owner-defined minimum'; END IF;
IF NEW.transaction_percentage>100 OR NEW.transaction_fixed>1000000 OR NEW.withdrawal_fee>1000000 THEN RAISE EXCEPTION 'Invalid fees'; END IF;
NEW.admin_user_id:=_uid; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION app_private.set_seller_withdrawal_block(_seller uuid,_block boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _uid uuid:=auth.uid(); _admin boolean:=public.has_role(auth.uid(),'admin'); _before jsonb; BEGIN
IF _uid IS NULL OR _block IS NULL OR length(trim(coalesce(_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Authorization and reason required'; END IF;
IF NOT _admin AND (NOT _block OR NOT public.has_staff_permission(_uid,'freeze_seller_withdrawals') OR NOT EXISTS(SELECT 1 FROM manager_seller_assignments WHERE manager_user_id=_uid AND seller_user_id=_seller)) THEN RAISE EXCEPTION 'Only owner can release; assigned staff permission required to block'; END IF;
IF _seller=_uid OR NOT EXISTS(SELECT 1 FROM profiles WHERE user_id=_seller) OR EXISTS(SELECT 1 FROM user_roles WHERE user_id=_seller AND role IN ('admin','employee','manager','partner')) THEN RAISE EXCEPTION 'Invalid seller'; END IF;
PERFORM 1 FROM profiles WHERE user_id=_seller FOR UPDATE;
SELECT to_jsonb(b) INTO _before FROM seller_withdrawal_blocks b WHERE seller_user_id=_seller;
INSERT INTO seller_withdrawal_blocks(seller_user_id,blocked_by,reason,active) VALUES(_seller,_uid,trim(_reason),_block) ON CONFLICT(seller_user_id) DO UPDATE SET active=_block,reason=EXCLUDED.reason,blocked_by=_uid,updated_at=now();
INSERT INTO staff_audit_log(staff_user_id,action,entity_type,entity_id,before,after) VALUES(_uid,CASE WHEN _block THEN 'block_seller_withdrawals' ELSE 'release_seller_withdrawals' END,'seller',_seller::text,_before,jsonb_build_object('active',_block,'reason',trim(_reason)));
INSERT INTO notifications(user_id,title,message,type,created_by) VALUES(_seller,CASE WHEN _block THEN 'Saques em análise' ELSE 'Saques liberados' END,CASE WHEN _block THEN 'Novos saques estão temporariamente bloqueados para análise. Login, vendas e saldo permanecem inalterados.' ELSE 'O bloqueio de novos saques foi removido pelo responsável.' END,'info',_uid);
END $$;
CREATE OR REPLACE FUNCTION public.set_seller_withdrawal_block(_seller uuid,_block boolean,_reason text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT app_private.set_seller_withdrawal_block($1,$2,$3) $$;
REVOKE ALL ON FUNCTION public.set_seller_withdrawal_block(uuid,boolean,text),app_private.set_seller_withdrawal_block(uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_seller_withdrawal_block(uuid,boolean,text),app_private.set_seller_withdrawal_block(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.enforce_staff_withdrawal_block() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM 1 FROM profiles WHERE user_id=NEW.user_id FOR UPDATE;
IF EXISTS(SELECT 1 FROM seller_withdrawal_blocks WHERE seller_user_id=NEW.user_id AND active) AND (TG_OP='INSERT' OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','processing','completed','paid'))) THEN RAISE EXCEPTION 'Saques bloqueados para análise'; END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION app_private.enforce_staff_withdrawal_block() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER trg_staff_withdrawal_block BEFORE INSERT OR UPDATE ON public.withdrawals FOR EACH ROW EXECUTE FUNCTION app_private.enforce_staff_withdrawal_block();